<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Acme Retail - Quality Goods</title>
  <style>
    :root {
      --primary: #2563eb;
      --primary-hover: #1d4ed8;
      --bg: #ffffff;
      --surface: #f3f4f6;
      --text: #111827;
      --text-muted: #4b5563;
      --border: #e5e7eb;
      --focus-ring: #60a5fa;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: system-ui, -apple-system, sans-serif;
      color: var(--text);
      background: var(--bg);
      line-height: 1.5;
    }

    /* Accessibility */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border-width: 0;
    }

    .skip-link {
      position: absolute;
      top: -40px;
      left: 0;
      background: var(--primary);
      color: white;
      padding: 8px;
      z-index: 100;
      transition: top 0.2s;
    }

    .skip-link:focus { top: 0; }

    :focus-visible {
      outline: 3px solid var(--focus-ring);
      outline-offset: 2px;
      border-radius: 2px;
    }

    @media (prefers-reduced-motion: reduce) {
      * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }

    /* Layout Components */
    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 16px;
    }

    header {
      border-bottom: 1px solid var(--border);
      padding: 16px 0;
    }

    .header-content {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .logo {
      font-size: 1.5rem;
      font-weight: bold;
      color: var(--text);
      text-decoration: none;
    }

    nav ul {
      list-style: none;
      padding: 0;
      margin: 0;
      display: flex;
      gap: 24px;
      flex-wrap: wrap;
    }

    nav a {
      color: var(--text-muted);
      text-decoration: none;
      font-weight: 500;
    }

    nav a:hover, nav a[aria-current="page"] { color: var(--text); }

    main:focus { outline: none; } /* handled by skip link target */

    section { margin: 64px 0; }

    h1, h2, h3 { line-height: 1.2; }
    h2 { font-size: 2rem; margin-bottom: 24px; border-bottom: 2px solid var(--surface); padding-bottom: 8px;}

    /* Product Grid */
    .product-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
      list-style: none;
      padding: 0;
      margin: 0;
    }

    .card {
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .card:hover {
      transform: translateY(-4px);
      box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1);
    }

    .card-img-wrapper {
      aspect-ratio: 1;
      background: var(--surface);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .card-img-placeholder {
       width: 100%; height: 100%;
       background-image: linear-gradient(45deg, #e5e7eb 25%, transparent 25%, transparent 75%, #e5e7eb 75%, #e5e7eb), linear-gradient(45deg, #e5e7eb 25%, transparent 25%, transparent 75%, #e5e7eb 75%, #e5e7eb);
       background-size: 20px 20px;
       background-position: 0 0, 10px 10px;
    }

    .card-content {
      padding: 16px;
      flex-grow: 1;
      display: flex;
      flex-direction: column;
    }

    .card h3 {
      margin: 0 0 8px 0;
      font-size: 1.125rem;
    }

    .card-link {
        text-decoration: none;
        color: inherit;
    }

    .card-link:hover h3 { text-decoration: underline; }

    .price {
      font-weight: bold;
      font-size: 1.25rem;
      margin-bottom: 16px;
    }

    .price-original {
        text-decoration: line-through;
        color: var(--text-muted);
        font-size: 1rem;
        font-weight: normal;
        margin-left: 8px;
    }

    .btn {
      background: var(--primary);
      color: white;
      border: none;
      padding: 10px 16px;
      border-radius: 6px;
      font-weight: 500;
      cursor: pointer;
      width: 100%;
      margin-top: auto;
      transition: background 0.2s;
    }

    .btn:hover { background: var(--primary-hover); }

    /* Editorial Section */
    .editorial {
      background: var(--surface);
      border-radius: 12px;
      padding: 40px;
      display: grid;
      gap: 32px;
      align-items: center;
    }

    @media (min-width: 768px) {
        .editorial { grid-template-columns: 1fr 1fr; }
    }

    .editorial-content h3 { font-size: 1.75rem; margin-top: 0; }

    .editorial-img {
        width: 100%;
        aspect-ratio: 4/3;
        background: #d1d5db;
        border-radius: 8px;
    }

    /* Footer */
    footer {
      background: var(--surface);
      padding: 48px 0;
      margin-top: 64px;
    }

    .footer-content {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 32px;
    }

    .footer-col h2 {
      font-size: 1.125rem;
      border: none;
      padding: 0;
      margin-bottom: 16px;
    }

    .footer-col ul { list-style: none; padding: 0; margin: 0; }
    .footer-col li { margin-bottom: 8px; }
    .footer-col a { color: var(--text-muted); text-decoration: none; }
    .footer-col a:hover { text-decoration: underline; }
  </style>
</head>
<body>

  <!-- React Root -->
  <div id="root"></div>

  <!-- React Dependencies (Development versions for standalone HTML) -->
  <script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

  <script type="text/babel">
    const { useState, useEffect } = React;

    // Component: Header
    const Header = () => (
      <header>
        <div className="container header-content">
          <a href="/" className="logo">Acme Retail</a>
          <nav aria-label="Primary">
            <ul>
              <li><a href="/" aria-current="page">Home</a></li>
              <li><a href="/shop">Shop All</a></li>
              <li><a href="/new">New Arrivals</a></li>
              <li><a href="/deals">Deals</a></li>
            </ul>
          </nav>
        </div>
      </header>
    );

    // Component: Product Card
    const ProductCard = ({ product }) => {
      const { id, name, price, originalPrice, isSale } = product;

      return (
        <li>
          <article className="card">
            <div className="card-img-wrapper" aria-hidden="true">
              <div className="card-img-placeholder"></div>
            </div>
            <div className="card-content">
              <a href={`/product/${id}`} className="card-link">
                <h3>{name}</h3>
              </a>
              <div className="price">
                ${price.toFixed(2)}
                {originalPrice && (
                  <span className="price-original">
                     <span className="sr-only">Original price: </span>
                     ${originalPrice.toFixed(2)}
                  </span>
                )}
              </div>
              <button 
                type="button" 
                className="btn"
                aria-label={`Add to cart: ${name}`}
                onClick={() => alert(`Added ${name} to cart`)}
              >
                Add to Cart
              </button>
            </div>
          </article>
        </li>
      );
    };

    // Component: Product Section
    const ProductSection = ({ id, title, products }) => (
      <section aria-labelledby={`${id}-heading`} className="container">
        <h2 id={`${id}-heading`}>{title}</h2>
        <ul className="product-grid">
          {products.map(product => (
            <ProductCard key={product.id} product={product} />
          ))}
        </ul>
      </section>
    );

    // Component: Editorial Section
    const Editorial = () => (
      <section className="container">
        <div className="editorial">
          <div className="editorial-content">
             <h3>Sustainable Quality</h3>
             <p>Our spring collection is made entirely from recycled materials, ensuring you look good while doing good. Discover the new standards of modern manufacturing.</p>
             <a href="/sustainability" style={{display: 'inline-block', marginTop: '16px', fontWeight: 'bold', color: 'var(--primary)', textDecoration: 'none'}}>Read our story →</a>
          </div>
          <div className="editorial-img" role="img" aria-label="People wearing clothing made from recycled materials in a natural setting"></div>
        </div>
      </section>
    );

    // Component: Footer
    const Footer = () => (
      <footer>
        <div className="container footer-content">
          <nav className="footer-col" aria-label="Shop Footer">
            <h2>Shop</h2>
            <ul>
              <li><a href="/shop/mens">Men's</a></li>
              <li><a href="/shop/womens">Women's</a></li>
              <li><a href="/shop/accessories">Accessories</a></li>
            </ul>
          </nav>
          <nav className="footer-col" aria-label="Support Footer">
            <h2>Support</h2>
            <ul>
              <li><a href="/help">Help Center</a></li>
              <li><a href="/returns">Returns</a></li>
              <li><a href="/shipping">Shipping Info</a></li>
            </ul>
          </nav>
          <div className="footer-col">
            <h2 id="newsletter-heading">Newsletter</h2>
            <form aria-labelledby="newsletter-heading" onSubmit={(e) => { e.preventDefault(); alert('Subscribed!'); }}>
              <label htmlFor="email-input" className="sr-only">Email address</label>
              <input 
                type="email" 
                id="email-input" 
                required 
                placeholder="Enter your email" 
                style={{width: '100%', padding: '8px', marginBottom: '8px', border: '1px solid var(--border)', borderRadius: '4px'}}
              />
              <button type="submit" className="btn" style={{padding: '8px'}}>Subscribe</button>
            </form>
          </div>
        </div>
      </footer>
    );

    // Mock Data
    const featuredProducts = [
      { id: '1', name: 'Classic Cotton Tee', price: 29.99 },
      { id: '2', name: 'Everyday Denim Jacket', price: 89.99 },
      { id: '3', name: 'Minimalist Sneakers', price: 120.00 },
      { id: '4', name: 'Canvas Tote Bag', price: 24.99 },
    ];

    const dealsProducts = [
      { id: '5', name: 'Wool Blend Sweater', price: 45.00, originalPrice: 75.00 },
      { id: '6', name: 'Chino Trousers', price: 35.50, originalPrice: 59.99 },
      { id: '7', name: 'Leather Belt', price: 15.00, originalPrice: 30.00 },
      { id: '8', name: 'Puffer Vest', price: 49.99, originalPrice: 89.99 },
    ];

    // Main App
    const App = () => {
      // Manage skip link focus
      useEffect(() => {
         document.title = "Acme Retail - Quality Goods";
      }, []);

      return (
        <React.Fragment>
          <a href="#maincontent" className="skip-link">Skip to main content</a>

          <Header />

          <main id="maincontent" tabIndex="-1">
            <div className="container" style={{marginTop: '32px'}}>
              <h1 style={{fontSize: '2.5rem', margin: '0 0 16px 0'}}>Spring Collection 2026</h1>
              <p style={{fontSize: '1.25rem', color: 'var(--text-muted)', margin: 0}}>Fresh styles for the new season.</p>
            </div>

            <ProductSection 
              id="featured" 
              title="Featured Products" 
              products={featuredProducts} 
            />

            <Editorial />

            <ProductSection 
              id="deals" 
              title="Today's Deals" 
              products={dealsProducts} 
            />
          </main>

          <Footer />
        </React.Fragment>
      );
    };

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
